mapper.update:
UPDATE feeding_record
SET feed_date = #{feedDate},
    feed_total_kg = #{feedTotalKg},
    remark = #{remark},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, pond_id, feed_date, feed_total_kg, remark, created_at, updated_at
FROM feeding_record
WHERE id = #{id}

SELECT id, pond_id, feed_date, feed_total_kg, remark, created_at, updated_at
FROM feeding_record
WHERE pond_id = #{pondId}
  AND feed_date = #{feedDate}
LIMIT 1

SELECT id, pond_id, feed_date, feed_total_kg, remark, created_at, updated_at
FROM feeding_record
WHERE pond_id = #{pondId}
ORDER BY feed_date DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM feeding_record
WHERE pond_id = #{pondId}
